// ПРОХОД 1: извлекаем структурированные числа из договора и сверки.
const d=$json;
const system=`Ты извлекаешь структурированные данные из документов коммерческой аренды NNN. Возвращай ТОЛЬКО валидный JSON по схеме, без markdown. Проценты — числом (напр. 4.2). Денежные суммы — числом без разделителей. Нет значения — null.`;
const user=`Извлеки данные, ЧЁТКО различая ДОГОВОР и СВЕРКУ.

ИЗ ДОГОВОРА (contract): pro_rata_share_pct — доля арендатора, ЗАФИКСИРОВАННАЯ В ДОГОВОРЕ (НЕ бери из сверки!); controllable_cap_pct — лимит годового роста контролируемых расходов; management_fee_cap_pct — лимит комиссии за управление; excluded_expenses — статьи, которые договор ЗАПРЕЩАЕТ включать; reconciliation_due_days; dispute_period_days — срок на оспаривание; base_year.
ИЗ СВЕРКИ (reconciliation): line_items — ВСЕ статьи с суммами; stated_total — заявленный итог; applied_share_pct — доля, ФАКТИЧЕСКИ применённая в сверке; tenant_share_amount; estimates_credited; prior_year_controllable; current_year_controllable; management_fee_applied_pct — процент комиссии в сверке; management_fee_amount; payment_deadline_days — за сколько дней требуют оплату.

СХЕМА: {"contract":{"pro_rata_share_pct":null,"controllable_cap_pct":null,"management_fee_cap_pct":null,"excluded_expenses":[],"reconciliation_due_days":null,"dispute_period_days":null,"base_year":null},"reconciliation":{"line_items":[{"name":"","amount":0}],"stated_total":null,"applied_share_pct":null,"tenant_share_amount":null,"estimates_credited":null,"balance_due":null,"prior_year_controllable":null,"current_year_controllable":null,"management_fee_applied_pct":null,"management_fee_amount":null,"payment_deadline_days":null}}

=== ДОГОВОР ===
${d.contract_text}

=== СВЕРКА ===
${d.reconciliation_text}`;
return [{ json:{ email:d.email, property_name:d.property_name, currency:d.currency, source:d.source, contract_text:d.contract_text, reconciliation_text:d.reconciliation_text, body: JSON.stringify({ model:'llama-3.3-70b-versatile', temperature:0, response_format:{type:'json_object'}, messages:[{role:'system',content:system},{role:'user',content:user}] }) }}];

const meta=$('🧠 Запрос: извлечь данные').first().json;
let raw=$json.choices?.[0]?.message?.content||'';
raw=String(raw).replace(/```json/gi,'').replace(/```/gi,'').trim();
let ex; try{ ex=JSON.parse(raw);}catch(e){ ex={}; }
return [{ json:{ email:meta.email, property_name:meta.property_name, currency:meta.currency, source:meta.source, contract_text:meta.contract_text, reconciliation_text:meta.reconciliation_text, extracted:ex } }];

// ТОЧНЫЙ РАСЧЁТ нарушений по извлечённым числам (без ИИ).
const d=$json; const ex=d.extracted||{}; const C=ex.contract||{}; const R=ex.reconciliation||{}; const cur=d.currency||'USD';
const num=v=>typeof v==='number'&&!isNaN(v)?v:(typeof v==='string'&&v.trim()!==''&&!isNaN(+v)?+v:null);
const cs=num(C.pro_rata_share_pct), applied=num(R.applied_share_pct), total=num(R.stated_total);
const money=n=>Math.round(n).toLocaleString('ru-RU')+' '+cur; const fmt=n=>'≈ '+money(n);
const findings=[]; let totalOver=0; const addAmt=a=>{ if(typeof a==='number'&&!isNaN(a)) totalOver+=a; };
// 1) Доля
if(cs!=null&&applied!=null&&total!=null&&Math.abs(applied-cs)>0.001){ const a=total*(applied-cs)/100; addAmt(a); findings.push({priority:'Высокий',amount:fmt(a),issue:`Применена доля ${applied}% вместо ${cs}% по договору`,detail:`Расходы распределены по доле ${applied}%, а договор фиксирует ${cs}%. Переплата = ${money(total)} × (${applied}%−${cs}%) = ${fmt(a)}.`}); }
// 2) Запрещённые расходы
const kw=[/roof|крыш/i,/parking|парков/i,/capital|капит/i,/deprecia|износ|амортиз/i,/interest|процент/i,/leasing|procure|attract|привлеч|лизинг/i,/income tax|налог на приб/i];
const items=Array.isArray(R.line_items)?R.line_items:[]; let exclSum=0; const exclNames=[];
for(const it of items){ const nm=it.name||''; const am=num(it.amount); if(am!=null&&kw.some(re=>re.test(nm))){ exclSum+=am; exclNames.push(`${nm} (${money(am)})`);} }
if(exclSum>0&&cs!=null){ const a=exclSum*cs/100; addAmt(a); findings.push({priority:'Высокий',amount:fmt(a),issue:`В расходы включены запрещённые договором статьи: ${exclNames.join(', ')}`,detail:`Договор исключает эти статьи. Ваша доля = ${money(exclSum)} × ${cs}% = ${fmt(a)}.`}); }
// 3) Cap
const cap=num(C.controllable_cap_pct), prior=num(R.prior_year_controllable), curr=num(R.current_year_controllable);
if(cap!=null&&prior!=null&&curr!=null&&prior>0){ const g=(curr-prior)/prior*100; if(g>cap+0.001){ const excess=curr-prior*(1+cap/100); const a=cs!=null?excess*cs/100:null; if(a!=null)addAmt(a); findings.push({priority:'Средний',amount:a!=null?fmt(a):'',issue:`Контролируемые расходы выросли на ${g.toFixed(1)}% при лимите ${cap}%`,detail:`Рост с ${money(prior)} до ${money(curr)} превышает лимит ${cap}%/год. Сверхлимит ≈ ${money(excess)}${a!=null?`, ваша доля ${fmt(a)}`:''}.`}); } }
// 4) Management fee
const feeCap=num(C.management_fee_cap_pct), feePct=num(R.management_fee_applied_pct), feeAmt=num(R.management_fee_amount);
if(feeCap!=null&&feePct!=null&&feeAmt!=null&&feePct>feeCap+0.001){ const exFee=feeAmt*(feePct-feeCap)/feePct; const a=cs!=null?exFee*cs/100:null; if(a!=null)addAmt(a); findings.push({priority:'Средний',amount:a!=null?fmt(a):'',issue:`Комиссия за управление ${feePct}% превышает лимит ${feeCap}%`,detail:`Сверхлимитная часть комиссии ≈ ${money(exFee)}${a!=null?`, ваша доля ${fmt(a)}`:''}.`}); }
// 9) Срок
const pay=num(R.payment_deadline_days), disp=num(C.dispute_period_days);
if(pay!=null&&disp!=null&&pay<disp){ findings.push({priority:'Средний',amount:'',issue:`Требуют оплату за ${pay} дн., хотя у вас ${disp} дн. на проверку и оспаривание`,detail:`Срок оплаты короче вашего права на оспаривание — платить до окончания проверки не обязательно.`}); }
// 8) Арифметика
const sumItems=items.reduce((s,it)=>s+(num(it.amount)||0),0);
if(total!=null&&sumItems>0&&Math.abs(sumItems-total)>1){ findings.push({priority:'Низкий',amount:'',issue:`Сумма статей (${money(sumItems)}) не сходится с заявленным итогом (${money(total)})`,detail:`Стоит перепроверить итог расходов.`}); }
return [{ json:{ email:d.email, property_name:d.property_name, currency:cur, source:d.source, contract_text:d.contract_text, reconciliation_text:d.reconciliation_text, computed_findings:findings, computed_total: totalOver>0?fmt(totalOver):'требует уточнения' } }];

// ПРОХОД 2: ИИ ТОЛЬКО ФОРМУЛИРУЕТ текст по уже посчитанным числам (не считает сам).
const d = $json;
const cf = JSON.stringify(d.computed_findings||[]);
const system = `Ты — помощник по NNN-аренде. Пишешь простым, дружелюбным языком для обычного арендатора; термины поясняй в скобках. НИКОГДА не упоминай технические названия полей. НЕ пересчитывай суммы — бери их ровно как в данных. Возвращай ТОЛЬКО валидный JSON, без markdown.`;
const user = `Вот ТОЧНО ПОСЧИТАННЫЕ нарушения (JSON, поле amount — готовая сумма переплаты, detail — пояснение):
${cf}

Итоговая переплата уже посчитана: '${d.computed_total}'.

ЗАДАЧА: для каждого нарушения сделай (1) находку понятным языком на основе issue/detail и (2) задачу — конкретное действие арендатора (что попросить/потребовать у арендодателя). priority бери из нарушения, potential_overcharge — из его amount. Добавь summary из 2-3 предложений простым языком. Если нарушений нет (пустой массив) — summary, что серьёзных расхождений не выявлено, и одна задача: сверить оригиналы и сохранить документы; total — 'нарушений не выявлено'.

В ответе поставь total_potential_overcharge = '${d.computed_total}' и confidence 0.9.

ВЕРНИ СТРОГО JSON: {"property_name":"${d.property_name}","confidence":0.9,"summary":"","total_potential_overcharge":"${d.computed_total}","findings":[{"issue":"","evidence_contract":"","evidence_reconciliation":"","potential_overcharge":""}],"tasks":[{"title":"","what_to_do":"","priority":"Высокий|Средний|Низкий","potential_overcharge":""}]}`;
return [{ json:{ email:d.email, property_name:d.property_name, currency:d.currency, source:d.source, computed_total:d.computed_total, body: JSON.stringify({ model:'llama-3.3-70b-versatile', temperature:0.2, response_format:{type:'json_object'}, messages:[{role:'system',content:system},{role:'user',content:user}] }) }}];

const meta = $('🧠 Собрать запрос к Groq').first().json;
let raw = $json.choices?.[0]?.message?.content || $json.message?.content || '';
raw = String(raw).replace(/```json/gi,'').replace(/```/gi,'').trim();
let data; try { data = JSON.parse(raw); } catch(e){ data = { parse_error:true, confidence:0, summary:'Не удалось автоматически разобрать ответ — перепроверим вручную.', findings:[], tasks:[{title:'Требуется ручная проверка', what_to_do:'Специалист посмотрит документы и вернётся с результатом.', priority:'Высокий', potential_overcharge:''}] }; }
const order={'Высокий':0,'Средний':1,'Низкий':2};
(data.tasks||[]).sort((a,b)=>(order[a.priority]??3)-(order[b.priority]??3));
const high=(data.tasks||[]).filter(t=>t.priority==='Высокий').length;
return [{ json:{ ...data, total_potential_overcharge: meta.computed_total || data.total_potential_overcharge, email:meta.email, currency:meta.currency, source:meta.source, property_name:data.property_name||meta.property_name, high_count:high, has_high:high>0, has_findings:(data.findings||[]).length>0, generated_at:new Date().toLocaleString('ru-RU') } }];

// Запрос на генерацию письма-претензии арендодателю на основе находок.
const d = $json;
const findings = JSON.stringify(d.findings||[]);
const system = `Ты юрист-помощник. Составь вежливое, но твёрдое официальное письмо-претензию от арендатора к арендодателю об оспаривании завышенных NNN-расходов. Деловой тон, на русском. Ссылайся на конкретные расхождения. Не выдумывай факты — только из переданных находок. Суммы — в валюте ${d.currency}. ВАЖНО: пиши обычным деловым языком, НИКОГДА не упоминай технические названия полей/переменных (pro_rata_share_pct, line_items, contract.* и т.п.) — только понятные формулировки с числами и процентами. Верни ТОЛЬКО текст письма, без пояснений и markdown.`;
const user = `Объект: ${d.property_name}. Возможная переплата: ${d.total_potential_overcharge||'требует уточнения'}. Находки (JSON): ${findings}. \nСтруктура письма: шапка (кому/от кого — оставь плейсхолдеры [Арендодатель], [Арендатор], [Дата]), суть, перечень спорных позиций со ссылкой на пункты договора, требование пересчитать и вернуть переплату/предоставить подтверждающие документы, срок ответа 30 дней, вежливое завершение.`;
return [{ json:{ ...d, body: JSON.stringify({ model:'llama-3.3-70b-versatile', temperature:0.3, messages:[{role:'system',content:system},{role:'user',content:user}] }) }}];

// Берём текст письма и кладём его и как вложение (.txt), и в данные для письма клиенту.
const d = $('📦 Распарсить ответ ИИ').first().json;
let letter = $json.choices?.[0]?.message?.content || '';
letter = String(letter).replace(/```/g,'').trim();
if (!letter) letter = 'Не удалось сгенерировать письмо автоматически.';
return [{ json:{ ...d, dispute_letter_text: letter }, binary:{ dispute_letter:{ data: Buffer.from(letter,'utf8').toString('base64'), mimeType:'text/plain', fileName:'Pretenziya_arendodatelyu.txt' } } }];
